 (4, 1, 'sector-04', 'SECTOR 04', 'MAKO PLATE', 'SUB-GRID LOGISTICS', NULL, NULL, NULL, 7821, 39803.30, 39.80, 4),
 (5, 1, 'sector-05', 'SECTOR 05', 'SLUM FORGE', 'EXHAUST & PIPING', NULL, NULL, NULL, 7924, 29514.01, 29.50, 5),
 (6, 1, 'sector-06', 'SECTOR 06', 'MARANELLO', 'CARBON AERO ASSETS', NULL, NULL, NULL, 1651, 53068.97, 53.10, 6),
