 (8, 2, 'wikimedia', 'ORG 01', 'Wikimedia Foundation', 'Free knowledge, in perpetuity', 'The mission of the Wikimedia Foundation is to empower and engage people around the world to collect and develop educational content under a free license or in the public domain, and to disseminate it effectively and globally.', 'Edit or fact-check Wikipedia articles; upload freely licensed media to Wikimedia Commons; add structured data on Wikidata; transcribe public-domain texts on Wikisource; join a local chapter or user group; report bugs and help with MediaWiki development.', 'Mission statement quoted from wikimediafoundation.org/about/mission (checked Nov 2026). The Foundation states it will keep useful information from its projects available on the internet free of charge, in perpetuity. Database dumps are published for offline mirrors.', 0, 0.00, NULL, 1),
 (9, 2, 'mozilla', 'ORG 02', 'Mozilla', 'The internet as a global public resource', 'Mozilla Manifesto, principle 2: the internet is a global public resource that must remain open and accessible. The Manifesto (2007) and the Pledge for a Healthy Internet (2017) guide Mozilla''s work.', 'Answer questions on Mozilla Support; translate Firefox and other products in Pontoon; file and triage bugs in Bugzilla; improve MDN Web Docs; contribute to Mozilla''s open-source code on GitHub.', 'Principle text quoted from mozilla.org/about/manifesto (checked Nov 2026). MDN Web Docs is an openly licensed reference for web technologies; its content is maintained in public repositories.', 0, 0.00, NULL, 2),
 (10, 2, 'linux-foundation', 'ORG 03', 'Linux Foundation', 'A neutral home for open technology', 'The Linux Foundation provides a neutral, trusted hub for developers to code, manage, and scale open technology projects.', 'Contribute code, docs, or reviews to a hosted project; take free LF Education courses; join an open working group; apply to or mentor through LFX Mentorship; help triage issues in the projects you use.', 'Mission line quoted from linuxfoundation.org/about (checked Nov 2026). The LF is a 501(c)(6) non-profit that hosts many projects under neutral governance.', 0, 0.00, NULL, 3);
